from fastapi import FastAPI
from fastapi.sse import ServerSentEvent
from pydantic import ValidationError

def test_sse_validation():
    # Test id with newline
    try:
        ServerSentEvent(id="id\nwith\nnewline")
        print("FAILED: ServerSentEvent accepted id with newline")
    except ValidationError as e:
        print("PASSED: ServerSentEvent rejected id with newline")
        assert "SSE 'id' must not contain newlines" in str(e)

    # Test event with newline
    try:
        ServerSentEvent(event="event\nwith\nnewline")
        print("FAILED: ServerSentEvent accepted event with newline")
    except ValidationError as e:
        print("PASSED: ServerSentEvent rejected event with newline")
        assert "SSE 'event' must not contain newlines" in str(e)

    # Test id with null character
    try:
        ServerSentEvent(id="id\0with\0null")
        print("FAILED: ServerSentEvent accepted id with null character")
    except ValidationError as e:
        print("PASSED: ServerSentEvent rejected id with null character")
        assert "SSE 'id' must not contain null characters" in str(e)

    # Test valid SSE
    try:
        ServerSentEvent(id="valid-id", event="valid-event", data="valid-data")
        print("PASSED: ServerSentEvent accepted valid input")
    except ValidationError as e:
        print(f"FAILED: ServerSentEvent rejected valid input: {e}")

if __name__ == "__main__":
    test_sse_validation()

