def test_sse_validation():
    # Test id with newline
    try:
        ServerSentEvent(id="id\nwith\nnewline")
        print("FAILED: ServerSentEvent accepted id with newline")
    except ValidationError as e:
        print("PASSED: ServerSentEvent rejected id with newline")
        assert "SSE 'id' must not contain newlines" in str(e)

    # Test event with newline
    try:
        ServerSentEvent(event="event\nwith\nnewline")
        print("FAILED: ServerSentEvent accepted event with newline")
    except ValidationError as e:
        print("PASSED: ServerSentEvent rejected event with newline")
        assert "SSE 'event' must not contain newlines" in str(e)

    # Test id with null character
