        ServerSentEvent(id="id\0with\0null")
        print("FAILED: ServerSentEvent accepted id with null character")
    except ValidationError as e:
        print("PASSED: ServerSentEvent rejected id with null character")
        assert "SSE 'id' must not contain null characters" in str(e)

    # Test valid SSE
    try:
        ServerSentEvent(id="valid-id", event="valid-event", data="valid-data")
        print("PASSED: ServerSentEvent accepted valid input")
